// Parse Gemini summaries, then build one Discord payload per group (tagged in Sort Split & Limit).
const responses = $input.all();
const articles  = $('Sort Split & Limit').all().map(a => a.json);

function truncateDescription(description, maxLength) {
  if (description.length <= maxLength) return description;
  const cutPoint = description.lastIndexOf('.', maxLength - 3);
  if (cutPoint > maxLength * 0.7) return description.substring(0, cutPoint + 1);
  return description.substring(0, maxLength - 3) + '...';
}
function getEmbedSize(e) {
  return (e.title?.length || 0) + (e.description?.length || 0) + (e.footer?.text?.length || 0);
}

// Merge Gemini summary back into the article
const enriched = articles.map((article, i) => {
  let summary = '', takeaway = '', tag = article._default_tag || '💡';
  try {
    const text = responses[i]?.json?.candidates?.[0]?.content?.parts?.[0]?.text;
    if (text) {
      const match = text.match(/\{[\s\S]*?\}/);
      if (match) {
        const parsed = JSON.parse(match[0]);
        summary  = parsed.summary  || '';
        takeaway = parsed.takeaway || '';
        tag      = parsed.tag      || tag;
      }
    }
  } catch (_) {
    summary = 'Summary unavailable'; takeaway = 'N/A';
  }
  return { ...article, ai_summary: summary, ai_takeaway: takeaway, ai_tag: tag };
});

// Group by _group
const byGroup = {};
for (const a of enriched) (byGroup[a._group] ||= []).push(a);

const now = new Date();
const dateStr = now.toLocaleDateString('fr-FR', { day:'2-digit', month:'short', year:'numeric', hour:'2-digit', minute:'2-digit' });

const out = [];
for (const [groupName, list] of Object.entries(byGroup)) {
  if (!list.length) continue;
  const { _webhook, _color, _label } = list[0];

  const embeds = [];
  let currentSize = 0;
  const MAX_TOTAL_SIZE = 5800;

  for (const data of list) {
    const pubDate = new Date(data.published_at);
    const pubDateStr = pubDate.toLocaleDateString('fr-FR', { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit' });

    let description = '';
    if (data.ai_summary)  description += `📝 **AI Summary:** ${data.ai_summary}\n\n`;
    if (data.ai_takeaway) description += `💡 **Key Takeaway:** ${data.ai_takeaway}\n\n`;
    if (data.gemini_score) description += `**Score: ${data.gemini_score}/100** ${data.gemini_reason ? '- ' + data.gemini_reason : ''}\n\n`;
    if (!data.ai_summary && data.description) {
      const desc = data.description || 'Pas de description disponible';
      description += desc.substring(0, 200) + (desc.length > 200 ? '...' : '');
    }

    const embed = {
      title: `${data.ai_tag || ''} ${data.category} | ${data.title}`.substring(0, 256),
      description,
      url: data.url,
      color: _color,
      footer: { text: `📍 ${data.source} | ⏰ ${pubDateStr}` }
    };

    let embedSize = getEmbedSize(embed);
    if (currentSize + embedSize > MAX_TOTAL_SIZE) {
      const remaining = MAX_TOTAL_SIZE - currentSize - 200;
      if (remaining > 100) {
        embed.description = truncateDescription(description, remaining);
        embeds.push(embed); currentSize += getEmbedSize(embed);
      }
      break;
    }
    if (embed.description.length > 1000) embed.description = truncateDescription(embed.description, 1000);
    embeds.push(embed); currentSize += embedSize;
  }

  if (!embeds.length) continue;

  out.push({
    json: {
      webhook_url: _webhook,
      content: `${_label} (AI-Curated) - ${embeds.length}/${list.length} article(s)\n\n📅 ${dateStr}\n━━━━━━━━━━━━━━━━━━━━━━━`,
      embeds
    }
  });
}
return out;
